package io.github.miklires.mclans.command;import io.github.miklires.mclans.clan.ClanService;import io.papermc.paper.command.brigadier.*;import java.util.*;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;public final class ClanChatCommand implements BasicCommand{private final ClanService service;public ClanChatCommand(ClanService service){this.service=service;}@Override public void execute(@NotNull CommandSourceStack source,@NotNull String[] args){CommandSender sender=source.getSender();if(!(sender instanceof Player player)){sender.sendMessage("Players only");return;}if(args.length==0){player.sendMessage("Usage: /cc <message>");return;}service.clanChat(player,String.join(" ",args));}}
